import { StrictMode, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { Editor, createEmptyTemplate, parseTemplate, type Template } from '../src'
import '../src/styles/document.css'
import '../src/styles/editor.css'
import { config } from './config'

const KEY = 'ptb:playground'
const load = (): Template => {
  try {
    const raw = localStorage.getItem(KEY)
    if (raw) return parseTemplate(JSON.parse(raw))
  } catch {}
  return createEmptyTemplate('My worksheet')
}

// Seeds (per-child randomisation) only matter once a template is finished and generated by a host app,
// so the builder has no seed input; previews/exports use this fixed one.
const PREVIEW_SEED = 'preview'

async function download(template: Template) {
  const res = await fetch('/api/pdf', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ template, seed: PREVIEW_SEED }),
  })
  if (!res.ok) throw new Error(await res.text())
  const url = URL.createObjectURL(await res.blob())
  window.open(url, '_blank')
}

function App() {
  const [initial] = useState(load)
  const [busy, setBusy] = useState(false)
  const run = async (t: Template) => {
    setBusy(true)
    try {
      await download(t)
    } catch (e) {
      alert((e as Error).message)
    } finally {
      setBusy(false)
    }
  }
  return (
    <Editor
      config={config}
      data={initial}
      onChange={(t) => localStorage.setItem(KEY, JSON.stringify(t))}
      actions={({ getTemplate }) => (
        <div className="ed-group">
          <button disabled={busy} onClick={() => run(getTemplate())}>{busy ? 'Rendering…' : 'Export PDF'}</button>
        </div>
      )}
    />
  )
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
